    let empty='';if(!workbench.items.length)empty=workbench.has_knowledge?`<div class="curation-empty"><b>${f.status==='open'?'当前没有待处理问题':'没有符合筛选条件的问题'}</b><span>${f.status==='open'?'自动治理已完成，您仍可主动查找知识进行调整。':'清除筛选后查看其他治理记录。'}</span><button data-action="curation-find-inline">查找知识并治理</button>${workbench.last_governance_at?`<small>最近一次自动治理：${fmtDate(workbench.last_governance_at)}</small>`:''}</div>`:`<div class="curation-empty"><b>还没有可治理的知识</b><span>先上传文档或同步数据源，系统完成解析和自动治理后会产生画像与待办。</span><button data-action="curation-upload">上传文档</button><button data-action="curation-source" class="secondary">接入数据源</button></div>`;
