  let filterTimer;$('[name=curation_query]')?.addEventListener('input',e=>{clearTimeout(filterTimer);filterTimer=setTimeout(()=>{state.curationFilters.query=e.target.value;state.curationSelectedCaseId=null;renderCuration()},300)});[['curation_status','status'],['curation_severity','severity'],['curation_case_type','case_type'],['curation_document','document_id']].forEach(([name,key])=>$(`[name=${name}]`)?.addEventListener('change',e=>{state.curationFilters[key]=e.target.value;state.curationSelectedCaseId=null;renderCuration()}));
