async function renderAnalysisRules(sets){if(!sets.some(x=>x.id===state.analysisRuleSetId))state.analysisRuleSetId=sets[0]?.id||null;const selected=sets.find(x=>x.id===state.analysisRuleSetId),rules=selected?await api(`/analysis/rule-sets/${selected.id}/rules`):[];actions(`<button id="analysis-set-add" class="secondary">新增规则集</button>${selected?'<button id="analysis-rule-add">新增规则</button>':''}`);$('#analysis-body').innerHTML=`<div class="analysis-rule-layout"><aside class="rule-set-list">${sets.length?sets.map(x=>`<article class="rule-set-card ${x.id===selected?.id?'active':''}" data-action="set-select" data-id="${x.id}"><div><b>${esc(x.name)}</b>${status(x.enabled?'available':'unavailable')}</div><p>${esc(x.description||'未填写用途')}</p><span>${esc(x.category)} · ${x.rule_count} 条规则</span><div>${btn('运行','set-run',x.id)}${btn('编辑','set-edit',x.id)}${btn('删除','set-delete',x.id,'danger')}</div></article>`).join(''):'<div class="inspector-empty">先创建一个规则集</div>'}</aside><section class="rule-detail-panel">${selected?`<div class="panel-heading"><div><b>${esc(selected.name)}</b><small>${esc(selected.description||'业务规则集合')}</small></div><span>${selected.auto_run?'自动运行':'手工运行'} · ${selected.auto_publish?'自动发布':'人工选择发布'}</span></div><div class="rule-card-list">${rules.length?rules.map(rule=>`<article class="analysis-rule-card"><div class="rule-card-head"><div><b>${esc(rule.name)}</b><small>V${rule.current_version} · 优先级 ${rule.priority} · 置信度 ${(Number(rule.confidence)*100).toFixed(0)}%</small></div>${status(rule.enabled?'available':'unavailable')}</div><p>${esc(analysisRuleNatural(rule.definition))}</p><details><summary>技术信息</summary><pre>${esc(rule.dsl)}</pre></details><div class="rule-card-actions">${btn('校验','rule-validate',rule.id)}${btn('版本记录','rule-versions',rule.id)}${btn('编辑','rule-edit',rule.id)}${btn('删除','rule-delete',rule.id,'danger')}</div></article>`).join(''):'<div class="empty-action"><b>这个规则集还没有规则</b><button id="analysis-rule-empty-add">新增第一条规则</button></div>'}</div>`:'<div class="empty-action"><b>请选择或创建规则集</b></div>'}</section></div>`;$('#analysis-set-add').onclick=()=>editAnalysisRuleSet();if(selected){$('#analysis-rule-add').onclick=()=>editAnalysisRule(selected);if($('#analysis-rule-empty-add'))$('#analysis-rule-empty-add').onclick=()=>editAnalysisRule(selected)}$('#analysis-body').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.stopPropagation();const set=sets.find(x=>x.id===b.dataset.id),rule=rules.find(x=>x.id===b.dataset.id);try{if(b.dataset.action==='set-select'){state.analysisRuleSetId=b.dataset.id;renderAnalysis()}if(b.dataset.action==='set-run')startAnalysisRun(set);if(b.dataset.action==='set-edit')editAnalysisRuleSet(set);if(b.dataset.action==='set-delete'&&confirm(`删除规则集 ${set.name}？`)){await api(`/analysis/rule-sets/${set.id}`,{method:'DELETE'});state.analysisRuleSetId=null;renderAnalysis()}if(b.dataset.action==='rule-validate'){const result=await api('/analysis/rules/validate',{method:'POST',body:{name:rule.name,definition:rule.definition,priority:rule.priority,confidence:rule.confidence,enabled:rule.enabled}});toast(result.valid?'Semantica 校验通过':'规则校验未通过',!result.valid)}if(b.dataset.action==='rule-versions')viewRuleVersions(rule);if(b.dataset.action==='rule-edit')editAnalysisRule(selected,rule);if(b.dataset.action==='rule-delete'&&confirm(`删除规则 ${rule.name}？`)){await api(`/analysis/rules/${rule.id}`,{method:'DELETE'});renderAnalysis()}}catch(err){toast(err.message,true)}}}
function inferenceRunSummary(detail,names){return `<div class="analysis-run-overview"><div><span>运行状态</span>${status(detail.status)}</div><div><span>完成进度</span><b>${detail.progress}%</b></div><div><span>推导结果</span><b>${detail.items?.length??detail.metrics?.persisted_results??0}</b></div><div><span>运行方式</span><b>${detail.mode==='publish'?'发布':'预览'}</b></div><div><span>总耗时</span><b>${detail.duration_ms==null?'—':chatDurationLabel(detail.duration_ms)}</b></div><div><span>规则集</span><b>${esc(names[detail.rule_set_id]||'—')}</b></div></div>`}
function inferenceFactDetail(item,ruleNames){if(!item)return '<div class="inspector-empty">选择一条结论查看证据</div>';return `<div class="inference-conclusion"><span>推导结论</span><h3>${esc(item.subject_name)} <i>${esc(item.predicate)}</i> ${esc(item.object_name||'—')}</h3><div><b>规则</b><span>${esc(ruleNames[item.rule_id]||'—')}</span><b>置信度</b><span>${(Number(item.confidence)*100).toFixed(1)}%</span><b>发布状态</b>${status(item.status)}</div></div><div class="inference-evidence"><b>为什么成立 · ${item.evidence?.length||0} 条前提</b>${(item.evidence||[]).map((evidence,index)=>`<article><i>${index+1}</i><div><b>${esc(evidence.subject_name||evidence.subject_token||'已验证事实')} ${esc(evidence.predicate||evidence.predicate_token||'关联')} ${esc(evidence.object_name||evidence.object_token||'')}</b><small>${evidence.premise_type==='inferred'?'来自另一条推导事实':esc(evidence.source_title||'来自已发布知识事实')}${evidence.page_number?` · 第 ${evidence.page_number} 页`:''}${evidence.structural_path?` · ${esc(evidence.structural_path)}`:''}</small>${evidence.source_snippet?`<p>${esc(evidence.source_snippet)}</p>`:''}</div>${evidence.source_chunk_id?`<button class="small secondary" data-analysis-fragment="${esc(evidence.source_chunk_id)}">查看来源</button>`:''}</article>`).join('')||'<div class="inspector-empty">当前证据没有可展开的来源片段</div>'}</div>`}
async function rollbackInferenceRun(row){const preview=await api(`/analysis/inference-runs/${row.id}/rollback-preview`);if(!preview.can_rollback){toast('本次运行没有可回滚的已发布事实',true);return}const names=preview.space_ids.map(id=>state.spaces.find(x=>x.id===id)?.name||'知识空间');const ok=await modal('回滚影响预览',`<div class="rollback-preview"><p>将失效 <b>${preview.invalidated_facts}</b> 条本次发布的推导事实</p><span>影响范围：${esc(names.join('、'))}</span><div>${preview.effects.map(x=>`<em>${esc(x)}</em>`).join('')}</div><small>历史运行、规则版本和证据链会继续保留。</small></div>`,async()=>api(`/analysis/inference-runs/${row.id}/rollback`,{method:'POST'}),'确认回滚');if(ok){toast('推理发布已回滚');renderAnalysis()}}
async function renderAnalysisResults(sets){actions('<button id="analysis-results-refresh">刷新</button>');const rows=await api('/analysis/inference-runs'),names=Object.fromEntries(sets.map(x=>[x.id,x.name]));if(!rows.some(x=>x.id===state.analysisSelectedRunId))state.analysisSelectedRunId=rows[0]?.id||null;const selected=rows.find(x=>x.id===state.analysisSelectedRunId),detail=selected?await api(`/analysis/inference-runs/${selected.id}`):null,activeSet=detail?sets.find(x=>x.id===detail.rule_set_id):null,rules=activeSet?await api(`/analysis/rule-sets/${activeSet.id}/rules`):[],ruleNames=Object.fromEntries(rules.map(x=>[x.id,x.name]));if(detail&&!detail.items.some(x=>x.id===state.analysisSelectedFactId))state.analysisSelectedFactId=detail.items[0]?.id||null;const fact=detail?.items.find(x=>x.id===state.analysisSelectedFactId),setName=id=>names[id]||'已删除规则集';$('#analysis-body').innerHTML=rows.length?`<div class="analysis-results-toolbar"><input id="analysis-run-search" placeholder="搜索规则集或状态"><select id="analysis-run-status"><option value="">全部状态</option><option value="running">运行中</option><option value="succeeded">已完成</option><option value="failed">失败</option></select></div><div class="analysis-result-layout"><aside id="analysis-run-list" class="analysis-run-list">${rows.map(x=>`<button class="analysis-run-card ${x.id===selected?.id?'active':''}" data-action="run-select" data-id="${x.id}" data-search="${esc(`${setName(x.rule_set_id)} ${STATUS_LABELS[x.status]||x.status}`)}" data-status="${x.status}"><div><b>${esc(setName(x.rule_set_id))}</b>${status(x.status)}</div><span>${x.mode==='publish'?'发布':'预览'} · ${(x.space_ids||[]).length} 个空间 · ${fmtDate(x.created_at)}</span>${progress(x.progress)}</button>`).join('')}</aside><section class="analysis-run-detail">${detail?`${inferenceRunSummary(detail,{...names,[detail.rule_set_id]:setName(detail.rule_set_id)})}${!activeSet?'<div class="trace-warning">原规则集已删除；历史运行、结论和证据仍可查看。</div>':''}${detail.error_message?`<div class="trace-warning">${esc(detail.error_message)}</div>`:''}<div class="analysis-run-actions">${detail.status==='failed'&&detail.job_id&&activeSet?'<button data-action="run-retry" data-id="'+detail.id+'">重试任务</button>':''}${detail.mode==='publish'&&detail.status==='succeeded'?'<button class="danger" data-action="run-rollback" data-id="'+detail.id+'">回滚发布</button>':''}</div><div class="inference-result-split"><div class="inference-fact-list">${detail.items.length?detail.items.map(x=>`<button class="${x.id===fact?.id?'active':''}" data-action="fact-select" data-id="${x.id}"><span><b>${esc(x.subject_name)}</b> <i>${esc(x.predicate)}</i> <b>${esc(x.object_name||'—')}</b></span><em>${(Number(x.confidence)*100).toFixed(1)}%</em></button>`).join(''):'<div class="inspector-empty">本次运行没有推导出新事实</div>'}</div><div class="inference-fact-detail">${inferenceFactDetail(fact,ruleNames)}</div></div>`:'<div class="inspector-empty">选择一条运行记录</div>'}</section></div>`:'<div class="panel empty-action"><b>还没有推理运行</b><span>从场景分析或规则中心发起第一次运行</span></div>';$('#analysis-results-refresh').onclick=renderAnalysis;const filter=()=>{const q=$('#analysis-run-search').value.trim().toLowerCase(),s=$('#analysis-run-status').value;$$('.analysis-run-card').forEach(x=>x.classList.toggle('hidden',Boolean(q&&!x.dataset.search.toLowerCase().includes(q)||s&&x.dataset.status!==s)))};if($('#analysis-run-search')){$('#analysis-run-search').oninput=filter;$('#analysis-run-status').onchange=filter}$('#analysis-body').onclick=async e=>{const b=e.target.closest('[data-action]'),fragment=e.target.closest('[data-analysis-fragment]')?.dataset.analysisFragment;if(fragment)return openFragment(fragment);if(!b)return;const row=rows.find(x=>x.id===b.dataset.id);try{if(b.dataset.action==='run-select'){state.analysisSelectedRunId=b.dataset.id;state.analysisSelectedFactId=null;renderAnalysis()}if(b.dataset.action==='fact-select'){state.analysisSelectedFactId=b.dataset.id;renderAnalysis()}if(b.dataset.action==='run-rollback')rollbackInferenceRun(row);if(b.dataset.action==='run-retry'){await api(`/jobs/${row.job_id}/retry`,{method:'POST'});toast('重试任务已提交');renderAnalysis()}}catch(err){toast(err.message,true)}};if(rows.some(x=>['queued','running'].includes(x.status)))state.analysisTimer=setTimeout(()=>state.view==='analysis'&&state.analysisTab==='results'&&renderAnalysis(),1500)}
const ANALYSIS_QUERY_EXAMPLES=[['all','查询全部关系','SELECT ?s ?p ?o\nWHERE {\n  ?s ?p ?o\n}\nLIMIT 50'],['entity','查询指定实体关联','SELECT ?s ?p ?o\nWHERE {\n  ?s ?p ?o .\n  FILTER(CONTAINS(STR(?s), "国联"))\n}\nLIMIT 50'],['inferred','查询适用范围事实','SELECT ?s ?p ?o\nWHERE {\n  ?s ?p ?o .\n  FILTER(CONTAINS(STR(?p), "适用于"))\n}\nLIMIT 50']];
function formatSparql(value){return value.trim().replace(/\s+(WHERE|LIMIT|OFFSET|ORDER BY|FILTER)\b/gi,'\n$1').replace(/\{\s*/g,'{\n  ').replace(/\s*\}/g,'\n}')}
function analysisQueryWorkspace(saved){const defaultQuery=ANALYSIS_QUERY_EXAMPLES[0][2];return `<div class="analysis-query-layout"><aside class="panel"><div class="toolbar"><b>保存的查询</b><span class="grow"></span><button id="analysis-query-save" class="small">保存</button></div><div class="saved-query-list">${saved.length?saved.map(x=>`<div class="saved-query-item" data-saved-query="${x.id}"><button class="link-button" data-action="query-load" data-id="${x.id}">${esc(x.name)}</button><span>${btn('编辑','query-edit',x.id)}${btn('删除','query-delete',x.id,'danger')}</span></div>`).join(''):'<div class="empty">暂无保存的查询</div>'}</div><div class="query-examples"><b>查询示例</b>${ANALYSIS_QUERY_EXAMPLES.map(([id,label])=>`<button class="secondary" data-query-example="${id}">${label}</button>`).join('')}</div></aside><section class="panel"><div class="analysis-query-editor">${analysisSpaceChecks(state.spaces.map(x=>x.id))}<label class="field"><span>只读 SPARQL</span><textarea id="analysis-sparql" class="code-editor">${esc(defaultQuery)}</textarea></label><div class="query-editor-actions"><button id="analysis-query-run">执行查询</button><button id="analysis-query-format" class="secondary">格式化</button><button id="analysis-query-clear" class="secondary">清空</button></div></div><div id="analysis-query-result" class="analysis-query-result"><div class="empty">选择知识空间并执行查询</div></div></section></div>`}
function renderAnalysisQueryResult(){const root=$('#analysis-query-result'),result=state.analysisQueryResult;if(!root||!result)return;const size=25,totalPages=Math.max(1,Math.ceil((result.rows||[]).length/size));state.analysisQueryPage=Math.min(totalPages,Math.max(1,state.analysisQueryPage));const start=(state.analysisQueryPage-1)*size,rows=(result.rows||[]).slice(start,start+size),columns=result.columns||[];root.innerHTML=`<div class="query-result-head"><div><b>${result.total} 条结果</b><span>${result.duration_ms} ms · ${result.projection?.triples||0} 个三元组</span></div><div><button id="analysis-query-copy" class="small secondary">复制结果</button><button id="analysis-query-csv" class="small secondary">导出 CSV</button></div></div>${table(columns,rows.map(row=>`<tr>${columns.map(column=>`<td class="mono">${esc(row[column]??'—')}</td>`).join('')}</tr>`))}<div class="query-pagination"><button class="secondary small" data-query-page="prev" ${state.analysisQueryPage<=1?'disabled':''}>上一页</button><span>${state.analysisQueryPage} / ${totalPages}</span><button class="secondary small" data-query-page="next" ${state.analysisQueryPage>=totalPages?'disabled':''}>下一页</button></div>`;root.onclick=async e=>{const page=e.target.closest('[data-query-page]')?.dataset.queryPage;if(page){state.analysisQueryPage+=page==='next'?1:-1;renderAnalysisQueryResult()}if(e.target.closest('#analysis-query-copy')){await navigator.clipboard.writeText(JSON.stringify(result.rows||[],null,2));toast('结果已复制')}if(e.target.closest('#analysis-query-csv')){const quote=value=>`"${String(value??'').replace(/"/g,'""')}"`,csv=[columns.map(quote).join(','),...(result.rows||[]).map(row=>columns.map(c=>quote(row[c])).join(','))].join('\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`知识查询-${Date.now()}.csv`;a.click();URL.revokeObjectURL(url)}}}
async function saveAnalysisQuery(saved,x=null){const current=$('#analysis-sparql')?.value||x?.query_text||'',spaces=[...$$('[name=analysis_space]:checked')].map(el=>el.value);const ok=await modal(x?'编辑查询':'保存查询',field('name','名称',x?.name||'','text','required')+check('enabled','启用',x?.enabled??true),async d=>api(x?`/analysis/saved-queries/${x.id}`:'/analysis/saved-queries',{method:x?'PUT':'POST',body:{...d,query_type:'sparql',space_ids:x?x.space_ids:spaces,query_text:x?x.query_text:current,config:x?.config||{}}}));if(ok){toast('查询已保存');renderAnalysis()}}
async function renderAnalysisQuery(){actions();const saved=await api('/analysis/saved-queries');$('#analysis-body').innerHTML=analysisQueryWorkspace(saved);$('#analysis-query-save').onclick=()=>saveAnalysisQuery(saved);$('#analysis-query-format').onclick=()=>$('#analysis-sparql').value=formatSparql($('#analysis-sparql').value);$('#analysis-query-clear').onclick=()=>{$('#analysis-sparql').value='';state.analysisQueryResult=null;$('#analysis-query-result').innerHTML='<div class="empty">等待执行</div>'};$$('[data-query-example]').forEach(button=>button.onclick=()=>{$('#analysis-sparql').value=ANALYSIS_QUERY_EXAMPLES.find(x=>x[0]===button.dataset.queryExample)[2]});$('#analysis-query-run').onclick=async()=>{const button=$('#analysis-query-run'),spaces=[...$$('[name=analysis_space]:checked')].map(el=>el.value),query=$('#analysis-sparql').value.trim();if(!spaces.length){toast('至少选择一个知识空间',true);return}if(!query){toast('请输入 SPARQL 查询',true);return}button.disabled=true;button.textContent='查询中…';try{state.analysisQueryResult=await api('/analysis/sparql',{method:'POST',body:{space_ids:spaces,query}});state.analysisQueryPage=1;renderAnalysisQueryResult()}catch(err){toast(err.message,true);$('#analysis-query-result').innerHTML=`<div class="empty error"><b>查询未执行</b><span>${esc(err.message)}</span></div>`}finally{button.disabled=false;button.textContent='执行查询'}};$('#analysis-body').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=saved.find(row=>row.id===b.dataset.id);try{if(b.dataset.action==='query-load'){state.spaces.forEach(space=>{const input=$(`[name=analysis_space][value="${space.id}"]`);if(input)input.checked=(x.space_ids||[]).includes(space.id)});$('#analysis-sparql').value=x.query_text}if(b.dataset.action==='query-edit')saveAnalysisQuery(saved,x);if(b.dataset.action==='query-delete'&&confirm(`删除查询 ${x.name}？`)){await api(`/analysis/saved-queries/${x.id}`,{method:'DELETE'});renderAnalysis()}}catch(err){toast(err.message,true)}}}

async function renderAudits(){actions();const rows=await api('/audit-events');page('审计日志',table(['时间','动作','对象','对象 ID','操作者','详情'],rows.map(x=>`<tr><td>${fmtDate(x.created_at)}</td><td class="mono">${esc(x.action)}</td><td>${esc(x.object_type)}</td><td class="mono">${esc(x.object_id||'—')}</td><td class="mono">${esc(x.actor_id||'—')}</td><td class="truncate mono">${esc(JSON.stringify(x.detail||{}))}</td></tr>`)))}

window.addEventListener('popstate',()=>{if(state.user)go(location.hash.slice(1)||'dashboard',false)});
(async()=>{try{state.user=await api('/auth/me');showShell();await go(location.hash.slice(1)||'dashboard',false)}catch{showLogin()}})();
